package com.althair.create_pocketdynamo.data;

import com.althair.create_pocketdynamo.PocketDynamo;
import com.althair.create_pocketdynamo.ponder.PDPonderLang;
import com.tterrag.registrate.providers.ProviderType;

/**
 * English strings that are not tied to a registered block or item (those are generated by Registrate itself).
 * Every user-visible string in the mod goes through a lang key.
 */
public class PDLangEntries {
	private static final String ID = PocketDynamo.MOD_ID;

	public static void register() {
		PocketDynamo.registrate().addDataGenerator(ProviderType.LANG, prov -> {
			prov.add("itemGroup." + ID + ".main", "Create: Pocket Dynamo");

			prov.add(ID + ".kinetics.portable_motor.rotation_speed", "RPM");

			prov.add(ID + ".gui.goggles.battery", "Battery:");
			prov.add(ID + ".gui.goggles.consumption", "draining");
			prov.add(ID + ".gui.goggles.empty", "Battery empty");
			prov.add(ID + ".gui.goggles.solar_panel", "Solar panel:");
			prov.add(ID + ".gui.goggles.generating", "generating");
			prov.add(ID + ".subtitle.motor_start", "Portable Motor powers up");

			prov.add(ID + ".tooltip.battery", "Battery:");
			prov.add(ID + ".tooltip.speed", "Speed:");
			prov.add(ID + ".tooltip.max_speed", "Max speed: %1$s RPM");
			prov.add(ID + ".tooltip.max_output", "Max output:");

			// Recipe viewer (JEI / EMI) description pages.
			prov.add(ID + ".recipe_info.motor.description",
				"Turns Forge Energy from its internal battery into Rotational Force, anywhere. Speed and direction are selected on its value panel.");
			prov.add(ID + ".recipe_info.motor.stats",
				"Max speed: %1$s RPM. Stress capacity at max speed: %2$s SU. Battery: %3$s FE.");
			prov.add(ID + ".recipe_info.motor.drain",
				"Drains %1$s FE per tick for each RPM it spins at, plus the energy needed by the load it carries. Faster costs more.");
			prov.add(ID + ".recipe_info.solar_panel.description",
				"Generates Forge Energy from sunlight and pushes it into adjacent cables, motors and batteries. Needs open sky; night and rain reduce its output.");
			prov.add(ID + ".recipe_info.solar_panel.stats",
				"Output: up to %1$s FE per tick in full sunlight. Internal buffer: %2$s FE.");
			prov.add(ID + ".recipe_info.energy_cable.description",
				"Carries Forge Energy. It connects on its own to other cables and to any block that accepts energy.");
			prov.add(ID + ".recipe_info.energy_cable.stats",
				"Moves up to %1$s FE per tick through each segment.");
			prov.add(ID + ".generic.unit.rpm", "RPM");
			prov.add(ID + ".generic.unit.fe", "FE");
			prov.add(ID + ".generic.unit.fe_per_tick", "FE/t");

			// Ponder scene, tag and shared texts are compiled from the storyboards themselves.
			PDPonderLang.provide(prov::add);
		});
	}
}
